    private boolean ispositivedouble(String doub) {
        double number;
        try
        {
            number = Double.parseDouble(doub);
            if (number < 0)
                return false;
        }
        catch(NumberFormatException nfe)
        {
             return false;
        }
        return true;
    }

    private boolean checklatitude(String lat)
    {
        double latitude;
        try
        {
            latitude = Double.parseDouble(lat);
            if ((latitude > 90) || (latitude <  -90) )
                return false;
        }
        catch(NumberFormatException nfe)
        {
             return false;
        }
        return true;
    }

    private boolean checklongitude(String lng) {
        double longitude;
        try
        {
            longitude = Double.parseDouble(lng);
            if ((longitude > 180) || (longitude < -180))
                return false;
        }
        catch(NumberFormatException nfe)
        {
                return false;
        }
        return true;
    }
    
