    //Checks if all inputs are legal, and updates the location
    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
       
        Boolean ok = true, sok;
        String LocationName;
        double latitude=0, longitude=0, elevation = 0, offset=0;
        String  timezone;

        //Get location
        LocationName = jTextField1.getText();

        //Get latitude
        if (checklatitude(jTextField2.getText()) == true)
            latitude = Double.parseDouble(jTextField2.getText());
        else
            ok = false;


        //Get longitude
        if (checklongitude(jTextField3.getText()) == true)
            longitude = Double.parseDouble(jTextField3.getText());
        else
            ok = false;

        //Get timezone
        timezone = jComboBox1.getSelectedItem().toString();
        
        //Get elevation
        if (ispositivedouble(jTextField4.getText()) == true)
            elevation = Double.parseDouble(jTextField4.getText());
        else
            ok = false;

        //Get Candle Lighting Offset
        if (ispositivedouble(jTextField5.getText()) == true)
            offset = Double.parseDouble(jTextField5.getText());
        else
            ok = false;

       
      if (ok == true)
      {
          if (save == true)
          {
              main.saveconffile(LocationName, latitude, longitude, timezone, elevation, offset);
              //main.save_confs = true;
          }
          main.SetLocation(LocationName, latitude, longitude, timezone, elevation);
          if(jCheckBox2.isSelected() == true)
            main.SetCandleLightingOffset(offset);
          
          main.ShowZmanim();
          setVisible(false);
      }
    }//GEN-LAST:event_jButton1ActionPerformed

